def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]

    # The frame's width is the initial run of frame-colored cells in the top row.
    panel_w = 0
    while panel_w < w and grid[0][panel_w] == frame:
        panel_w += 1

    separators = [
        r for r in range(h)
        if all(grid[r][c] == frame for c in range(panel_w))
    ]
    panels = list(zip(separators, separators[1:]))

    # Count cells in each connected non-background object to the right.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(panel_w, w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            count = 0
            while stack:
                y, x = stack.pop()
                count += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and panel_w <= nx < w
                            and grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((color, count))

    out = [row[:panel_w] for row in grid]
    unused = objects[:]
    for top, bottom in panels:
        holes = [
            (r, c) for r in range(top + 1, bottom)
            for c in range(1, panel_w - 1)
            if grid[r][c] == 0
        ]
        match = next((obj for obj in unused if obj[1] == len(holes)), None)
        if match is not None:
            unused.remove(match)
            for r, c in holes:
                out[r][c] = match[0]
    return out
